import{_ as r,c as t,o as e,ae as i}from"./chunks/framework.DCU7Csu6.js";const g=JSON.parse('{"title":"Руководства","description":"Пошаговые руководства по созданию приложений с Wildberries TypeScript SDK","frontmatter":{"title":"Руководства","description":"Пошаговые руководства по созданию приложений с Wildberries TypeScript SDK","layout":"doc"},"headers":[],"relativePath":"ru/getting-started/tutorials/index.md","filePath":"ru/getting-started/tutorials/index.md"}'),s={name:"ru/getting-started/tutorials/index.md"};function l(n,a,o,p,d,h){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="руководства" tabindex="-1">Руководства <a class="header-anchor" href="#руководства" aria-label="Permalink to &quot;Руководства&quot;">​</a></h1><p>Подробные пошаговые руководства для освоения Wildberries TypeScript SDK.</p><blockquote><p><strong>English Version</strong> | <a href="./../../../getting-started/tutorials/">Русская версия</a></p></blockquote><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>Эти руководства помогут вам создавать реальные e-commerce решения для маркетплейса Wildberries. Каждое руководство включает полные рабочие примеры кода, которые вы можете использовать как основу для своих проектов.</p><hr><h2 id="доступные-руководства" tabindex="-1">Доступные руководства <a class="header-anchor" href="#доступные-руководства" aria-label="Permalink to &quot;Доступные руководства&quot;">​</a></h2><h3 id="_1-синхронизация-каталога-товаров" tabindex="-1">1. Синхронизация каталога товаров <a class="header-anchor" href="#_1-синхронизация-каталога-товаров" aria-label="Permalink to &quot;1. Синхронизация каталога товаров&quot;">​</a></h3><p><strong><a href="./product-catalog-sync.html">Начать руководство →</a></strong></p><p>Узнайте, как синхронизировать каталог товаров с маркетплейсом Wildberries.</p><ul><li>Получение категорий товаров из Wildberries</li><li>Создание карточек товаров с атрибутами</li><li>Загрузка медиафайлов (изображений)</li><li>Динамическое обновление цен</li></ul><p><strong>Время:</strong> 30 минут | <strong>Сложность:</strong> Начальный уровень</p><hr><h3 id="_2-обработка-заказов" tabindex="-1">2. Обработка заказов <a class="header-anchor" href="#_2-обработка-заказов" aria-label="Permalink to &quot;2. Обработка заказов&quot;">​</a></h3><p><strong><a href="./order-fulfillment.html">Начать руководство →</a></strong></p><p>Создайте полный рабочий процесс обработки заказов FBS (Fulfillment by Seller).</p><ul><li>Получение новых заказов из Wildberries</li><li>Обновление статусов заказов</li><li>Генерация этикеток и стикеров для отправки</li><li>Управление поставками</li></ul><p><strong>Время:</strong> 45 минут | <strong>Сложность:</strong> Средний уровень</p><hr><h3 id="_3-панель-аналитики" tabindex="-1">3. Панель аналитики <a class="header-anchor" href="#_3-панель-аналитики" aria-label="Permalink to &quot;3. Панель аналитики&quot;">​</a></h3><p><strong><a href="./analytics-dashboard.html">Начать руководство →</a></strong></p><p>Создайте комплексную панель аналитики с данными о продажах, запасах и показателях эффективности.</p><ul><li>Агрегация данных о продажах и расчёт KPI</li><li>Отслеживание уровня запасов на складах</li><li>Мониторинг возвратов и отзывов клиентов</li><li>Генерация отчётов в различных форматах</li></ul><p><strong>Время:</strong> 60 минут | <strong>Сложность:</strong> Средний уровень</p><hr><h3 id="_4-мультимодульная-интеграция" tabindex="-1">4. Мультимодульная интеграция <a class="header-anchor" href="#_4-мультимодульная-интеграция" aria-label="Permalink to &quot;4. Мультимодульная интеграция&quot;">​</a></h3><p><strong><a href="./multi-module-integration.html">Начать руководство →</a></strong></p><p>Создайте продвинутую систему, интегрирующую несколько модулей SDK для сложных бизнес-процессов.</p><ul><li>Объединение модулей Products, Orders, Analytics и Reports</li><li>Реализация межмодульных конвейеров данных</li><li>Обработка ошибок и повторов между модулями</li><li>Создание надёжных автоматизированных рабочих процессов</li></ul><p><strong>Время:</strong> 90 минут | <strong>Сложность:</strong> Продвинутый уровень</p><hr><h2 id="предварительные-требования" tabindex="-1">Предварительные требования <a class="header-anchor" href="#предварительные-требования" aria-label="Permalink to &quot;Предварительные требования&quot;">​</a></h2><p>Перед началом любого руководства убедитесь, что у вас есть:</p><ul><li>✅ <strong>Node.js ≥ 20.0.0</strong> установлен</li><li>✅ <strong>Аккаунт продавца Wildberries</strong> с доступом к API</li><li>✅ <strong>SDK установлен</strong> через <code>npm install daytona-wildberries-typescript-sdk</code></li><li>✅ <strong>Базовые знания TypeScript</strong></li><li>✅ Пройден <a href="./../quickstart.html">Быстрый старт</a></li></ul><hr><h2 id="подход-к-обучению" tabindex="-1">Подход к обучению <a class="header-anchor" href="#подход-к-обучению" aria-label="Permalink to &quot;Подход к обучению&quot;">​</a></h2><p>Каждое руководство следует единой структуре:</p><ol><li><strong>Что вы создадите</strong> - Обзор конечного результата</li><li><strong>Цели обучения</strong> - Навыки, которые вы получите</li><li><strong>Предварительные требования</strong> - Что нужно перед началом</li><li><strong>Пошаговые инструкции</strong> - Детальное руководство по реализации</li><li><strong>Полный код</strong> - Полностью рабочий пример</li><li><strong>Следующие шаги</strong> - Куда двигаться дальше</li></ol><hr><h2 id="рекомендуемыи-путь-обучения" tabindex="-1">Рекомендуемый путь обучения <a class="header-anchor" href="#рекомендуемыи-путь-обучения" aria-label="Permalink to &quot;Рекомендуемый путь обучения&quot;">​</a></h2><p>Для лучшего освоения материала рекомендуем проходить руководства по порядку:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Синхронизация каталога товаров (Начальный)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. Обработка заказов (Средний)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. Панель аналитики (Средний)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>4. Мультимодульная интеграция (Продвинутый)</span></span></code></pre></div><p>Каждое руководство основывается на концепциях из предыдущих, помогая вам постепенно освоить SDK.</p><hr><h2 id="дополнительные-ресурсы" tabindex="-1">Дополнительные ресурсы <a class="header-anchor" href="#дополнительные-ресурсы" aria-label="Permalink to &quot;Дополнительные ресурсы&quot;">​</a></h2><ul><li><strong><a href="/daytona-wildberries-typescript-sdk/api/">Справочник API</a></strong> - Полная документация API</li><li><strong><a href="/daytona-wildberries-typescript-sdk/examples/">Примеры</a></strong> - Фрагменты кода и сценарии использования</li><li><strong><a href="/daytona-wildberries-typescript-sdk/ru/guides/best-practices.html">Лучшие практики</a></strong> - Рекомендации по использованию SDK</li><li><strong><a href="/daytona-wildberries-typescript-sdk/ru/guides/troubleshooting.html">Устранение неполадок</a></strong> - Типичные проблемы и решения</li></ul><hr><h2 id="получить-помощь" tabindex="-1">Получить помощь <a class="header-anchor" href="#получить-помощь" aria-label="Permalink to &quot;Получить помощь&quot;">​</a></h2><p>Если вы столкнулись с проблемами при работе с руководствами:</p><ol><li>Проверьте <a href="/daytona-wildberries-typescript-sdk/ru/guides/troubleshooting.html">Руководство по устранению неполадок</a></li><li>Поищите в <a href="https://github.com/salacoste/daytona-wildberries-typescript-sdk/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>Откройте новый issue с подробным описанием проблемы</li></ol><hr><p><a href="./../">Назад к Началу работы</a> | <a href="./product-catalog-sync.html">Начать с Синхронизации каталога →</a></p>`,52)])])}const u=r(s,[["render",l]]);export{g as __pageData,u as default};
